import re
import time
import wrapt
import sys
import six

from requests.exceptions import ConnectionError
from .exception import NoRouteToHostException,  TimeoutParameterException, BtsConnectionError, CannotEnableServices


def _map_last_exception():
    error_message = str(sys.exc_info()[1])
    result = re.match(r".* \[Errno (?P<error_number>\d*)\]", error_message)
    if not result:
        return BtsConnectionError(error_message)
    elif result.group('error_number') == '113':
        return NoRouteToHostException(error_message)
    elif result.group('error_number') == '110':
        error_message = 'eNB TRS service site is not reachable. Please ensure that host 192.168.255.129 is fully functional.'
        return NoRouteToHostException(error_message)
    else:
        return BtsConnectionError(error_message)


@wrapt.decorator
def exception_handler(wrapped, instance, args, kwargs):
    """Handler of connection exceptions."""
    try:
        return wrapped(*args, **kwargs)
    except CannotEnableServices as e:
        raise e
    except ConnectionError:
        raise _map_last_exception()
    except Exception as e:
        raise BtsConnectionError(str(e))


def timeout(function):
    """Timeout decorator"""
    def _wrap(inst, *args, **kwargs):
        exception = None
        timeout = args[0] if len(args) >= 1 else kwargs.get('timeout', six.get_function_defaults(function)[0])
        step = args[1] if len(args) >= 2 else kwargs.get('step', six.get_function_defaults(function)[1])
        start_time = time.time()
        new_time = start_time
        while new_time - start_time <= timeout:
            try:
                return function(inst, *args, **kwargs)
            except Exception as e:
                exception = e
            time.sleep(step)
            new_time = time.time()
        raise exception if exception else TimeoutParameterException("Timeout must be a positive number")
    return _wrap
